--- a/training/level-1/L1-004-text-stats/textStats.mjs
+++ b/training/level-1/L1-004-text-stats/textStats.mjs
@@ -0,0 +1,12 @@
+export function textStats(input) {
+  if (input == null) {
+    return '';
+  }
+  const text = String(input);
+  const chars = Array.from(text).length;
+  const trimmed = text.trim();
+  const words = trimmed === '' ? 0 : text.split(/\s+/).filter(Boolean).length;
+  const normalized = text.replace(/\r\n|\r/g, '\n');
+  const lines = normalized === '' ? 0 : normalized.split('\n').length;
+  return Object.freeze({ chars, words, lines });
+}

